CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory_PostgreSQL" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory_PostgreSQL" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Notifications" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "Title" text NOT NULL,
    "Message" text NOT NULL,
    "Type" text NOT NULL,
    "IsRead" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Notifications" PRIMARY KEY ("Id")
);

CREATE TABLE "Payments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Plan" text NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Currency" text NOT NULL,
    "Provider" text NOT NULL,
    "OrderId" text NOT NULL,
    "PaymentId" text,
    "Signature" text,
    "Status" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "PaidAt" timestamp with time zone,
    CONSTRAINT "PK_Payments" PRIMARY KEY ("Id")
);

CREATE TABLE "PaymentWebhookEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventId" text NOT NULL,
    "EventType" text NOT NULL,
    "UserId" integer,
    "RazorpayPaymentId" text,
    "RazorpayOrderId" text,
    "ReceivedAt" timestamp with time zone NOT NULL,
    "Processed" boolean NOT NULL,
    CONSTRAINT "PK_PaymentWebhookEvents" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" character varying(150) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "PasswordHash" text NOT NULL,
    "Role" text NOT NULL,
    "EmailVerified" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedOn" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "PasswordResetTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "TokenHash" character varying(128) NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "IsUsed" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PasswordResetTokens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PasswordResetTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Subscriptions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Plan" character varying(50) NOT NULL,
    "MonthlyAuditLimit" integer NOT NULL,
    "MonthlyPrice" numeric(18,2) NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone,
    "IsActive" boolean NOT NULL,
    "Status" character varying(30) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "PaymentProvider" character varying(50),
    "ExternalSubscriptionId" character varying(200),
    CONSTRAINT "PK_Subscriptions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Subscriptions_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Websites" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Url" character varying(500) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedOn" timestamp with time zone NOT NULL,
    "UserId" integer NOT NULL,
    CONSTRAINT "PK_Websites" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Websites_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AuditHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "WebsiteId" integer NOT NULL,
    "Url" text NOT NULL,
    "StatusCode" integer NOT NULL,
    "ResponseTimeMs" integer NOT NULL,
    "IsReachable" boolean NOT NULL,
    "Message" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "HttpVersion" text,
    "Server" text,
    "ContentType" text,
    "ContentLength" bigint,
    "IsRedirect" boolean,
    "RedirectLocation" text,
    "IsSslValid" boolean,
    "Title" text,
    "MetaDescription" text,
    "H1Count" integer,
    "H2Count" integer,
    "Images" integer,
    "ImagesWithoutAlt" integer,
    "SeoScore" integer,
    CONSTRAINT "PK_AuditHistories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AuditHistories_Websites_WebsiteId" FOREIGN KEY ("WebsiteId") REFERENCES "Websites" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AuditResults" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "WebsiteId" integer NOT NULL,
    "StatusCode" integer NOT NULL,
    "ResponseTimeMs" bigint NOT NULL,
    "IsSslValid" boolean NOT NULL,
    "IsReachable" boolean NOT NULL,
    "AuditDate" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AuditResults" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AuditResults_Websites_WebsiteId" FOREIGN KEY ("WebsiteId") REFERENCES "Websites" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_AuditHistories_WebsiteId" ON "AuditHistories" ("WebsiteId");

CREATE INDEX "IX_AuditResults_WebsiteId" ON "AuditResults" ("WebsiteId");

CREATE UNIQUE INDEX "IX_PasswordResetTokens_TokenHash" ON "PasswordResetTokens" ("TokenHash");

CREATE INDEX "IX_PasswordResetTokens_UserId" ON "PasswordResetTokens" ("UserId");

CREATE UNIQUE INDEX "IX_PaymentWebhookEvents_EventId" ON "PaymentWebhookEvents" ("EventId");

CREATE UNIQUE INDEX "IX_Subscriptions_UserId" ON "Subscriptions" ("UserId");

CREATE INDEX "IX_Websites_UserId" ON "Websites" ("UserId");

